          "sourceUrl": "https://www.google.com/maps/place/La+Rumbantela+Latin+Club/@52.078919,4.3078491,17z/data=!4m8!3m7!1s0x47c5b725631f75e5:0xf0a7541a9fa97b07!8m2!3d52.078919!4d4.3078491!9m1!1b1!16s%2Fg%2F11b6q46vlj?entry=ttu&g_ep=EgoyMDI2MDkzMC4wIKXMDSoASAFQAw%3D%3D",
