          "displayText": "Leuk ouderwets bruin cafe in de mooiste buurt van Den Haag. Publiek is over het algemeen wel iets ouder, ik gok 55 +\nDaarintegen was de sfeer gemoedelijk, barkeeper erg vriendelijk en enthousiast.",
