          "rating": 5,
          "text": "Erg lekker eten tegen een goede prijs. Zeer vriendelijk personeel. Goede sfeer onder de bezoekers. Voelt als een buurtcafé waar je ook als je niet uit de buurt komt zeer welkom bent. we zouden zeker nog een keer terug komen.",
