          "rating": 5,
          "text": "Wat een heerlijk café. Toegankelijke sfeer met vriendelijk personeel. Vooral de Amstel vaasjes doen het goed. Af en toe een happie naast het drankie. En als het moet en je band is lek en je bent het allemaal even kwijt, wordt er een Uber geregeld. Gouwe toko.",
          "displayText": "Wat een heerlijk café. Toegankelijke sfeer met vriendelijk personeel. Vooral de Amstel vaasjes doen het goed. Af en toe een happie naast het drankie. En als het moet en je band is lek en je bent het allemaal even kwijt, wordt er een Uber geregeld. Gouwe toko.",
          "originalLanguage": "nl",
          "translations": {
            "en": "What a lovely café. A welcoming atmosphere with friendly staff. The small Amstel beers are especially popular. Every now and then, a little snack alongside the drink. And if necessary, when you have a flat tyre and feel completely lost, they arrange an Uber. A great place."
          },
          "translationProvider": "editorial translation",
          "publishedLabel": "4 jaar geleden",
          "publishedLabels": {
            "nl": "4 jaar geleden",
            "en": "4 years ago"
          },
