          "rating": 5,
          "text": "Ik had hier een klein feestje van een jarige  vriendin.\nHet is een ouderwets toegankelijk kroegje wat je vroeger vaak zag. Het deed me denken aan mijn jeugd, als mijn vader me wel eens meenam naar (zijn)kroegje.\nBarpersoneel is attent en snel.",
          "displayText": "Ik had hier een klein feestje van een jarige  vriendin.\nHet is een ouderwets toegankelijk kroegje wat je vroeger vaak zag. Het deed me denken aan mijn jeugd, als mijn vader me wel eens meenam naar (zijn)kroegje.\nBarpersoneel is attent en snel.",
          "originalLanguage": "nl",
          "translations": {
            "en": "I had a small party here for a friend's birthday.\nIt is an old-fashioned, welcoming little pub of the kind you used to see often. It reminded me of my childhood, when my father would sometimes take me along to (his) little pub.\nThe bar staff are attentive and quick."
          },
