          "rating": 4,
          "text": "Op de terugweg van het strand, weg uit de drukte, een buurtcafeetje. Vriendelijk en kleinschalig. Centraal gelegen en daarom goed bereikbaar. Nu niet verder gekomen dan een pintje en bitterballen, maar het smaakte zeker naar meer!",
          "displayText": "Op de terugweg van het strand, weg uit de drukte, een buurtcafeetje. Vriendelijk en kleinschalig. Centraal gelegen en daarom goed bereikbaar. Nu niet verder gekomen dan een pintje en bitterballen, maar het smaakte zeker naar meer!",
          "originalLanguage": "nl",
          "translations": {
            "en": "On the way back from the beach, away from the crowds, a little neighbourhood café. Friendly and small-scale. Centrally located and therefore easy to reach. This time we got no further than a pint and bitterballen, but it certainly left us wanting more!"
          },
          "translationProvider": "editorial translation",
          "publishedLabel": "5 jaar geleden",
