          "text": "Gezellig buurtcafé zonder pretenties. Naast de drankjes ook prima borrelhappen. Men kent elkaar, over het algemeen. Helaas beperkt zon op het terras. Soms livemuziek.",
          "displayText": "Gezellig buurtcafé zonder pretenties. Naast de drankjes ook prima borrelhappen. Men kent elkaar, over het algemeen. Helaas beperkt zon op het terras. Soms livemuziek.",
