          "rating": 5,
          "text": "Vriendelijke mensen, nette prijzen, gecombineerde met vakmanschap. Maandagmiddag geopend, veel winkels in het dorp Voorschoten zijn dan gesloten, kon gelijk terrcht. Met kopje koffie. Ben er nu 3 keer geweest, naar volle tevredenheid van mijn vrouw 😃 …",
          "displayText": "Vriendelijke mensen, nette prijzen, gecombineerde met vakmanschap. Maandagmiddag geopend, veel winkels in het dorp Voorschoten zijn dan gesloten, kon gelijk terrcht. Met kopje koffie. Ben er nu 3 keer geweest, naar volle tevredenheid van mijn vrouw 😃 …",
          "originalLanguage": "nl",
          "translations": {
            "en": "Friendly people, fair prices, combined with craftsmanship. Open on Monday afternoons, when many shops in the village of Voorschoten are closed; I was able to be seen straight away. With a cup of coffee. I have now been there three times, to my wife's complete satisfaction 😃 …"
          },
