          "rating": 5,
          "text": "Ik laat normaal nooit recensies achter, maar deze kapsalon is echt goed. Ik ben voor 20 euro goed geknipt door een man met veel ervaring, en had daar voor 9 euro extra een potje wax bij. 29 euro is in verhouding heel sterk tegenover de andere kappers in voorschoten waar je al meer dan 30 euro neerlegt voor alleen knippen.",
          "displayText": "Ik laat normaal nooit recensies achter, maar deze kapsalon is echt goed. Ik ben voor 20 euro goed geknipt door een man met veel ervaring, en had daar voor 9 euro extra een potje wax bij. 29 euro is in verhouding heel sterk tegenover de andere kappers in voorschoten waar je al meer dan 30 euro neerlegt voor alleen knippen.",
          "originalLanguage": "nl",
          "translations": {
            "en": "I normally never leave reviews, but this hair salon is really good. I had a good haircut for 20 euros from a man with a lot of experience, and got a jar of wax for an extra 9 euros. 29 euros compares very favourably with the other hairdressers in Voorschoten, where you already pay more than 30 euros for just a haircut."
          },
