          "rating": 5,
          "text": "Wat een onwijs gezellig welkom als je hier binnen stapt. Heel veel dank voor het organiseren van het kerstklaverjassen. Volle bak, heel goed geregeld, fantastische prijzen, de hapjes en de soep waren voortreffelijk. Kom gauw weer langs....\nRene en\nMarianne",
          "displayText": "Wat een onwijs gezellig welkom als je hier binnen stapt. Heel veel dank voor het organiseren van het kerstklaverjassen. Volle bak, heel goed geregeld, fantastische prijzen, de hapjes en de soep waren voortreffelijk. Kom gauw weer langs....\nRene en\nMarianne",
          "originalLanguage": "nl",
          "translations": {
            "en": "What an incredibly warm welcome when you walk in here. Many thanks for organising the Christmas klaverjas card tournament. A full house, very well organised, fantastic prizes, and the snacks and soup were excellent. We will be back soon....\nRene and\nMarianne"
          },
