          "rating": 4,
          "text": "Leuke plaats om even te ontspannen. Je kan er darten, poolen en tafelvoetballen onder genot van een drankje en een hapje. Heb geen eten besteld dus kan ik dat helaas niet voor jullie beoordelen. De dames achter de bar waren vriendelijke en spontane dames met een goede service.",
          "displayText": "Leuke plaats om even te ontspannen. Je kan er darten, poolen en tafelvoetballen onder genot van een drankje en een hapje. Heb geen eten besteld dus kan ik dat helaas niet voor jullie beoordelen. De dames achter de bar waren vriendelijke en spontane dames met een goede service.",
          "originalLanguage": "nl",
          "translations": {
            "en": "A nice place to relax for a while. You can play darts, pool and table football while enjoying a drink and a snack. I did not order food, so unfortunately I cannot judge that for you. The ladies behind the bar were friendly and outgoing, with good service."
          },
