          "rating": 5,
          "text": "Dit is echt de beste bakkerij in Oranjeboomstraat  ik kom hier al jaren!!  elke dag vers warm brood breed assortiment aan eten en huishouden..  wat ook heel fijn is dat je hier je pakketjes kunt ophalen! Top service altijd klantvriendelijk en netjes en schoon! Kortom het is hier meer dan alleen een bakkerij! 👌🏻",
          "displayText": "Dit is echt de beste bakkerij in Oranjeboomstraat  ik kom hier al jaren!!  elke dag vers warm brood breed assortiment aan eten en huishouden..  wat ook heel fijn is dat je hier je pakketjes kunt ophalen! Top service altijd klantvriendelijk en netjes en schoon! Kortom het is hier meer dan alleen een bakkerij! 👌🏻",
          "originalLanguage": "nl",
          "translations": {
            "en": "This really is the best bakery on Oranjeboomstraat; I have been coming here for years!! Fresh warm bread every day, a wide range of food and household products.. It is also really convenient that you can collect your parcels here! Great service, always customer-friendly, tidy and clean! In short, it is more than just a bakery! 👌🏻"
          },
          "translationProvider": "editorial translation",
