          "rating": 4,
          "text": "Lekkere gevulde warme broodjes. Ik haal altijd mijn sesamringetjes en plaatbrood daar, altijd ontzettend lekker. Je kan der ook tomaten, melk, sla en jogurt enz. ff snel kopen als je wat vergeten bent.",
          "displayText": "Lekkere gevulde warme broodjes. Ik haal altijd mijn sesamringetjes en plaatbrood daar, altijd ontzettend lekker. Je kan der ook tomaten, melk, sla en jogurt enz. ff snel kopen als je wat vergeten bent.",
          "originalLanguage": "nl",
          "translations": {
            "en": "Delicious warm filled rolls. I always get my sesame rings and flatbread there; always incredibly tasty. You can also quickly buy tomatoes, milk, lettuce, yoghurt and so on if you have forgotten something."
          },
          "translationProvider": "editorial translation",
          "publishedLabel": "5 jaar geleden",
