          "rating": 1,
          "text": "Slecht eten. Als het moet doe je het maar altijd spijt ivm met de prijs en qualiteit. Nooit echt vriendelijk. En als je van kk @postNL je pakketje weer eens niet bezorgd krijgt en het weereens daar aankomt kan je het niet ophalen want de openings tijden kloppen niet. Eerder een hinder dan handig. Sluiten die tent. Foto is van 18:43 terwijl er staat dat ze tot 20:00 open zijn",
          "displayText": "Slecht eten. Als het moet doe je het maar altijd spijt ivm met de prijs en qualiteit. Nooit echt vriendelijk. En als je van kk @postNL je pakketje weer eens niet bezorgd krijgt en het weereens daar aankomt kan je het niet ophalen want de openings tijden kloppen niet. Eerder een hinder dan handig. Sluiten die tent. Foto is van 18:43 terwijl er staat dat ze tot 20:00 open zijn",
          "originalLanguage": "nl",
          "translations": {
            "en": "Bad food. You go there if you have to, but always regret it because of the price and quality. Never really friendly. And when f***ing @postNL fails to deliver your parcel again and it ends up there yet again, you cannot collect it because the opening hours are wrong. More of a nuisance than convenient. Close the place. The photo was taken at 18:43, although it says they are open until 20:00."
          },
