          "rating": 4,
          "text": "Het is echt een dart kroeg.\nPerfect voor een portje te darten ook hebben ze vaak koppel toernooien waar je voor kan inschrijven.\nMaar is niet snel een kroeg met de sfeer dat alles er komt en snel een praatje maakt met onbekende.\nVerder wel gezellig en goed niets verkeerd voor een avondje",
          "displayText": "Het is echt een dart kroeg.\nPerfect voor een portje te darten ook hebben ze vaak koppel toernooien waar je voor kan inschrijven.\nMaar is niet snel een kroeg met de sfeer dat alles er komt en snel een praatje maakt met onbekende.\nVerder wel gezellig en goed niets verkeerd voor een avondje",
          "originalLanguage": "nl",
          "translations": {
            "en": "It really is a darts pub.\nPerfect for a game of darts, and they also often have pairs tournaments you can enter.\nBut it is not really the sort of pub where everyone turns up and quickly starts chatting to strangers.\nStill, it is friendly and good; nothing wrong with it for an evening out."
          },
