          "text": "Gister even met mijn vriendin hier geweest omdat we even moesten wachten tussen het avondeten en een feestje in de avond. De deur leek gesloten maar werd al snel opengedaan. We werden door zowel de eigenaren als de gasten erg vriendelijk ontvangen. Het is een echte bruine kroeg waar je gewoon lekker een pilsje kan drinken met Hazes o.i.d. Op de achtergrond.\nOns favoriete nummer van de avond: het kaartspel",
          "displayText": "Gister even met mijn vriendin hier geweest omdat we even moesten wachten tussen het avondeten en een feestje in de avond. De deur leek gesloten maar werd al snel opengedaan. We werden door zowel de eigenaren als de gasten erg vriendelijk ontvangen. Het is een echte bruine kroeg waar je gewoon lekker een pilsje kan drinken met Hazes o.i.d. Op de achtergrond.\nOns favoriete nummer van de avond: het kaartspel",
          "originalLanguage": "nl",
          "translations": {
            "en": "I went here with my girlfriend yesterday because we had some time to wait between dinner and a party that evening. The door seemed closed but was soon opened. Both the owners and the guests welcomed us very warmly. It is a real traditional Dutch pub where you can simply enjoy a beer with Hazes or something similar in the background.\nOur favourite song of the evening: het kaartspel."
          },
          "translationProvider": "editorial translation",
