          "rating": 5,
          "text": "Helaas door de Corona op dit moment gesloten, kijk uit naar de tijd dat deze echte bruine kroeg weer open gaat. de gastvrijheid van Theo en Joke zorgt voor een geweldige stapavond met de best getapte heineken biertjes :-)",
          "displayText": "Helaas door de Corona op dit moment gesloten, kijk uit naar de tijd dat deze echte bruine kroeg weer open gaat. de gastvrijheid van Theo en Joke zorgt voor een geweldige stapavond met de best getapte heineken biertjes :-)",
          "originalLanguage": "nl",
          "translations": {
            "en": "Unfortunately closed at the moment because of coronavirus. I look forward to when this true traditional Dutch pub opens again. Theo and Joke’s hospitality makes for a wonderful night out with the best poured Heineken beers :-)"
          },
