          "rating": 5,
          "text": "Vanochtend had ik mijn eerste afspraak bij Rima , zij en haar collega zijn super lief en professioneel. Ik ben super tevreden met de resultaat!\nBedankt voor jullie geduld 😊\nZeker aanraden! En tot de volgende keer 🌷",
          "displayText": "Vanochtend had ik mijn eerste afspraak bij Rima , zij en haar collega zijn super lief en professioneel. Ik ben super tevreden met de resultaat!\nBedankt voor jullie geduld 😊\nZeker aanraden! En tot de volgende keer 🌷",
          "originalLanguage": "nl",
          "translations": {
            "en": "This morning I had my first appointment with Rima. She and her colleague are very kind and professional. I am extremely happy with the result!\nThank you for your patience 😊\nDefinitely recommended! See you next time 🌷"
          },
          "translationProvider": "editorial translation",
