          "authorUrl": "https://www.google.com/maps/contrib/103311171413494080492/reviews?hl=nl",
          "photoUrl": "https://lh3.googleusercontent.com/a/ACg8ocK6dmXyT9Fx5sflSO_s3HpvIePay4_16QARhyZ4uCfpL_K1zQ=w81-h81-p-rp-mo-br100",
          "rating": 5,
          "text": "Ik ben blij dat ik Rima 7 jaar geleden heb gevonden. Ik ben tevreden omdat ze een kapster is die eindelijk luistert naar mij hoe ik mijn haar wil laten knippen. Als ik een afspraak maak ben ik zo aan de beurt. Ze werkt snel en ze heeft betaalbare prijzen. Iedereen is vriendelijk in de kapsalon. Zeker een aanrader!",
          "displayText": "Ik ben blij dat ik Rima 7 jaar geleden heb gevonden. Ik ben tevreden omdat ze een kapster is die eindelijk luistert naar mij hoe ik mijn haar wil laten knippen. Als ik een afspraak maak ben ik zo aan de beurt. Ze werkt snel en ze heeft betaalbare prijzen. Iedereen is vriendelijk in de kapsalon. Zeker een aanrader!",
          "originalLanguage": "nl",
          "translations": {
            "en": "I am glad I found Rima 7 years ago. I am happy because she is a hairdresser who finally listens to how I want my hair cut. When I make an appointment, I am seen quickly. She works fast and her prices are affordable. Everyone in the salon is friendly. Definitely recommended!"
          },
          "translationProvider": "editorial translation",
          "publishedLabel": "4 jaar geleden",
