          "text": "ik en mijn vriendin waren hier samen naartoe gegaan om onze haren te knippen in laagjes en we zijn allebei heel blij met onze haartjes niet alleen knippen ze het mooi maar wordt het super goed in model gebracht, de service was ook super ze bleef vragen of we het mooi vonden  en legde ook effe uit hoe we het zelf zo thuis kunnen doen ik raad deze kapper zeker aan.\nEn ook voor de heren mijn vriend komt hier ook altijd en dat doen ze ook super netjes.",
