          "text": "Werd door m'n neef uitgenogigd om daar te eten. In 1 woord gewldig!! Heerlijke zachte biefstuk, waar je mes in ''wegzakt'' Bord vol met heerlijke boontjes met gebakken krieltjes. Ongeloveloos, wordt in 'n soortement ''kast'' klaargemaakt!!  + gezellig pilsje/wijntje drinken. Geen wijnglazen zoals 't hoort, maar ''bomvolle'' glazen!! Proficiat Werkelijk 'n aanrader!! Ouwerwets gezellig!! (Was m'n verjaardagskado, heb dus niet betaald, ben wel gelijk vaste klant geworden!!)",
          "displayText": "Werd door m'n neef uitgenogigd om daar te eten. In 1 woord gewldig!! Heerlijke zachte biefstuk, waar je mes in ''wegzakt'' Bord vol met heerlijke boontjes met gebakken krieltjes. Ongeloveloos, wordt in 'n soortement ''kast'' klaargemaakt!!  + gezellig pilsje/wijntje drinken. Geen wijnglazen zoals 't hoort, maar ''bomvolle'' glazen!! Proficiat Werkelijk 'n aanrader!! Ouwerwets gezellig!! (Was m'n verjaardagskado, heb dus niet betaald, ben wel gelijk vaste klant geworden!!)",
          "originalLanguage": "nl",
          "translations": {
            "en": "My cousin invited me to eat there. In one word: fantastic!! Delicious tender steak that your knife “sinks into”, a plate full of delicious green beans and fried baby potatoes. Unbelievable: it is prepared in a sort of “cupboard”!! Plus a nice beer or wine. Not wine glasses as they should be, but glasses filled “to the brim”!! Congratulations. Truly recommended!! Old-fashioned friendliness!! (It was my birthday present, so I did not pay, but I immediately became a regular customer!!)"
          },
          "translationProvider": "editorial translation",
          "publishedLabel": "een jaar geleden",
          "publishedLabels": {
            "nl": "een jaar geleden",
            "en": "1 year ago"
          },
