          "authorUrl": "https://www.google.com/maps/contrib/117680007368779034663/reviews?hl=nl",
          "photoUrl": "https://lh3.googleusercontent.com/a-/ALV-UjVpG-e670llGu76fdxdeVDXfg18wsN-jb0w3HoPW8ftwZysewkzaA=w81-h81-p-rp-mo-ba12-br100",
          "rating": 5,
          "text": "Een bruin cafe zoals t hoort maar waarvan er steeds minder zijn. Waar de barman weet wie je bent en wat je drinkt. Kleedjes op tafel.  Heerlijk, niks hip, gewoon knus, gezellig en lekker rotterdams.",
          "displayText": "Een bruin cafe zoals t hoort maar waarvan er steeds minder zijn. Waar de barman weet wie je bent en wat je drinkt. Kleedjes op tafel.  Heerlijk, niks hip, gewoon knus, gezellig en lekker rotterdams.",
          "originalLanguage": "nl",
          "translations": {
            "en": "A traditional Dutch pub as it should be, but the kind there are fewer and fewer of. Where the barman knows who you are and what you drink. Tablecloths on the tables. Wonderful: nothing trendy, just cosy, friendly and properly Rotterdam."
          },
