          "rating": 5,
          "text": "Super gezellige mensen\nDeze mensen waren vandaag 7-7-25 bij ons aan boord van de river cruise Rotterdam om de verjaardag van mario te vieren en geloof mij dit was echt een succes\nMag ik jullie bedanken voor de super gezellige 2 uurtjes bij ons aan boord\nEn graag tot de volgende keer\nGroetjes john loef ( stuurman)",
          "displayText": "Super gezellige mensen\nDeze mensen waren vandaag 7-7-25 bij ons aan boord van de river cruise Rotterdam om de verjaardag van mario te vieren en geloof mij dit was echt een succes\nMag ik jullie bedanken voor de super gezellige 2 uurtjes bij ons aan boord\nEn graag tot de volgende keer\nGroetjes john loef ( stuurman)",
          "originalLanguage": "nl",
          "translations": {
            "en": "Such friendly people.\nThese people were aboard our River Cruise Rotterdam today, 7 July 2025, to celebrate Mario’s birthday, and believe me, it was a real success.\nMay I thank you for the wonderfully enjoyable 2 hours aboard with us?\nWe would love to see you next time.\nBest wishes, John Loef (helmsman)."
          },
