          "rating": 4,
          "text": "Nieuw Eldorado een leuk café waar zowel jongeren als de oudere klanten van verschillende nationaliteiten met elkaar gezellig een glas kunnen drinken met een goed stukje muziek en een hele ruime rookruimte waar ook nog een dansje gemaakt kan worden met in het weekend vaak een DJ al met al een gezellig Café !!!!!",
          "displayText": "Nieuw Eldorado een leuk café waar zowel jongeren als de oudere klanten van verschillende nationaliteiten met elkaar gezellig een glas kunnen drinken met een goed stukje muziek en een hele ruime rookruimte waar ook nog een dansje gemaakt kan worden met in het weekend vaak een DJ al met al een gezellig Café !!!!!",
          "originalLanguage": "nl",
          "translations": {
            "en": "New Eldorado is a nice café where younger and older customers of different nationalities can enjoy a friendly drink together with good music and a very spacious smoking area where you can even have a dance, often with a DJ at weekends. All in all, a welcoming café!!!!!"
          },
